import{_ as e,o as s,c as l,a2 as n}from"./chunks/framework.C2TvIV46.js";const i=JSON.parse('{"title":"変数モデル","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/variable-model.md","filePath":"ja/language/variable-model.md"}'),t={name:"ja/language/variable-model.md"};function o(p,a,c,d,r,g){return s(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="変数モデル" tabindex="-1">変数モデル <a class="header-anchor" href="#変数モデル" aria-label="Permalink to &quot;変数モデル&quot;">​</a></h1><p>Megalo の変数は、条件とアクションが使う型付きの値を保持します。種類はいくつかあります。自分で宣言するカスタム変数、読み取り専用の組み込みエンジン状態、プレイヤー／チーム／オブジェクトに付くメンバー変数です。</p><h2 id="カスタム変数" tabindex="-1">カスタム変数 <a class="header-anchor" href="#カスタム変数" aria-label="Permalink to &quot;カスタム変数&quot;">​</a></h2><p>カスタム変数はスクリプトのトップレベルにある <code>variables</code> ブロックで宣言します。</p><h3 id="宣言構文" tabindex="-1">宣言構文 <a class="header-anchor" href="#宣言構文" aria-label="Permalink to &quot;宣言構文&quot;">​</a></h3><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">special_death_type</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>各エントリ行は 4 つの部分からなります（スコープは <code>variables</code> 行そのものにあります）。</p><table tabindex="0"><thead><tr><th>部分</th><th>値</th></tr></thead><tbody><tr><td><strong>スコープ</strong></td><td><code>global</code>、<code>player</code>、<code>team</code>、<code>object</code></td></tr><tr><td><strong>ネットワーク状態</strong></td><td><code>local</code>、<code>networked</code>、<code>networked_high</code></td></tr><tr><td><strong>型</strong></td><td><code>number</code>、<code>timer</code>、<code>object</code>、<code>team</code>、<code>player</code></td></tr><tr><td><strong>初期値</strong></td><td>型に合うリテラルまたは定数</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">player</span><span class="megalo-text"> </span><span class="megalo-variable">killing_player</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">special_death_type</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">is_leader</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">game_start_vo</span><span class="megalo-text"> </span><span class="megalo-number">5</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">heard_game_start</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">object</span><span class="megalo-text"> </span><span class="megalo-variable">body</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">object</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">lifetime</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">team</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">object</span><span class="megalo-text"> </span><span class="megalo-variable">goal</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">vehicle_refresh</span><span class="megalo-text"> </span><span class="megalo-number">30</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>スコープキーワードは <code>variables</code> 行そのものに現れます（<code>variables global</code>、<code>variables player</code> など）。</p><h3 id="制限" tabindex="-1">制限 <a class="header-anchor" href="#制限" aria-label="Permalink to &quot;制限&quot;">​</a></h3><p>カスタム変数スロット数は各 <a href="/MegaloEvolved/beta/docs/ja/versions/">megalo バージョンページ</a> の <strong>Limits</strong> にあります — 例: <a href="/MegaloEvolved/beta/docs/ja/versions/49/#limits">49</a>、<a href="/MegaloEvolved/beta/docs/ja/versions/73/#limits">73</a>、<a href="/MegaloEvolved/beta/docs/ja/versions/107/#limits">107</a>、<a href="/MegaloEvolved/beta/docs/ja/versions/107-mcc/#limits">107 (MCC)</a>。上限を超えるとコンパイルに失敗します。</p><p>MCC Reach では、オーバーフローが有効なとき <a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger#action-scope"><code>temporary</code></a> 変数が未使用グローバルスロットへ溢れ得ます — <a href="/MegaloEvolved/beta/docs/ja/versions/107-mcc/#limits">107 (MCC) — Limits</a> と <a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings#temporary-variable-overflow">コンパイラ設定</a> を参照。</p><h3 id="型" tabindex="-1">型 <a class="header-anchor" href="#型" aria-label="Permalink to &quot;型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>型</th><th>保持するもの</th><th>初期値の例</th></tr></thead><tbody><tr><td><code>number</code></td><td>整数</td><td><code>0</code>、<code>25</code>、<code>k_hidden_slayer</code></td></tr><tr><td><code>timer</code></td><td>カウントダウンタイマー</td><td><code>5</code>、<code>flag_return_time</code></td></tr><tr><td><code>object</code></td><td>マップオブジェクト参照</td><td><code>none</code></td></tr><tr><td><code>team</code></td><td>チーム参照</td><td><code>none</code>、<code>attackers</code></td></tr><tr><td><code>player</code></td><td>プレイヤー参照</td><td><code>none</code></td></tr></tbody></table><p>Megalo は型安全です。変数の宣言型は引数として使われるときに検査され、不一致はコンパイル時エラーになります。</p><h3 id="ネットワーク状態" tabindex="-1">ネットワーク状態 <a class="header-anchor" href="#ネットワーク状態" aria-label="Permalink to &quot;ネットワーク状態&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状態</th><th>挙動</th></tr></thead><tbody><tr><td><code>local</code></td><td>ネットワークで同期されない。誤用防止のため、毎ティック開始時に初期値へリセットされる。</td></tr><tr><td><code>networked</code></td><td>全マシン間で同期される。帯域コストがある。</td></tr><tr><td><code>networked_high</code></td><td>より高い優先度で同期される。</td></tr></tbody></table><p>タイマーは常にネットワーク同期です — <code>local timer</code> の宣言はコンパイル時エラーです。</p><h3 id="スコープ" tabindex="-1">スコープ <a class="header-anchor" href="#スコープ" aria-label="Permalink to &quot;スコープ&quot;">​</a></h3><p>各スコープは、その種類のインスタンスごとに変数のコピーを持ちます。</p><table tabindex="0"><thead><tr><th>スコープ</th><th>コピー単位</th><th>アクセス例</th></tr></thead><tbody><tr><td><code>global</code></td><td>マッチ</td><td><code>my_counter</code></td></tr><tr><td><code>player</code></td><td>プレイヤー</td><td><code>current_player.is_leader</code></td></tr><tr><td><code>team</code></td><td>チーム</td><td><code>current_team.goal</code></td></tr><tr><td><code>object</code></td><td>オブジェクト</td><td><code>current_object.lifetime</code></td></tr></tbody></table><h2 id="メンバー変数" tabindex="-1">メンバー変数 <a class="header-anchor" href="#メンバー変数" aria-label="Permalink to &quot;メンバー変数&quot;">​</a></h2><p>オブジェクトスコープの変数（および組み込みプロパティ）はドット記法でアクセスします。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">score add </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">is_leader set_to </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">action set buy_zone</span><span class="megalo-operator">.</span><span class="megalo-text">phase_1_timer set_to haxoring_time_phase_1</span></span></code></pre></div><p>よく使う組み込みメンバー変数（<code>variables</code> ブロックでは宣言しない）:</p><table tabindex="0"><thead><tr><th>メンバー</th><th>対象</th><th>型</th><th>説明</th></tr></thead><tbody><tr><td><code>.score</code></td><td>player</td><td>number</td><td>プレイヤーの現在スコア</td></tr><tr><td><code>.team</code></td><td>player, object</td><td>team</td><td>所属チーム</td></tr><tr><td><code>.rating</code></td><td>player</td><td>number</td><td>Arena レーティング</td></tr><tr><td><code>.body</code></td><td>player</td><td>object</td><td>プレイヤーの物理オブジェクト</td></tr><tr><td><code>.user_data</code></td><td>object</td><td>number</td><td>Forge のユーザーデータフィールド</td></tr></tbody></table><h2 id="定数" tabindex="-1">定数 <a class="header-anchor" href="#定数" aria-label="Permalink to &quot;定数&quot;">​</a></h2><p>定数は <code>constants</code> ブロックで宣言する名前付き数値です。実行時に変更できず、変数ストレージコストもかかりません。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">constants</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">k_special_death_type_none</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">k_special_death_type_melee</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">k_special_death_type_headshot</span><span class="megalo-text"> </span><span class="megalo-number">5</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">k_cross_map_distance</span><span class="megalo-text"> </span><span class="megalo-number">400</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>定数は他の数値と同様、条件とアクションで名前により参照されます。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">condition if special_death_type equal_to k_special_death_type_headshot</span></span>
<span class="line"><span class="megalo-text">action set_score add headshot_bonus player killing_player</span></span></code></pre></div><h2 id="組み込み変数" tabindex="-1">組み込み変数 <a class="header-anchor" href="#組み込み変数" aria-label="Permalink to &quot;組み込み変数&quot;">​</a></h2><p>Megalo スクリプトは、<code>variables</code> ブロックで宣言しない組み込み変数名を通じてエンジン状態を読めます。条件や <code>set</code> のオペランドに通常の識別子として現れます。</p><p>型とゲームごとの可用性を含む完全な一覧は <a href="/MegaloEvolved/beta/docs/ja/language/enums/built-in-variables">組み込み変数</a> を参照。</p><p><code>game_options</code> ブロックで宣言したゲームオプションも、読み取り可能な定数になります（例: <code>kill_points</code>、<code>hidden_gametype</code>、<code>flag_return_time</code>）。</p><p>組み込み変数は <code>game_options</code> の <code>override</code> で上書きできます。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">game_options</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-number">25</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">round_count</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">round_time_limit</span><span class="megalo-text"> </span><span class="megalo-number">10</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>完全な一覧は <a href="/MegaloEvolved/beta/docs/ja/language/enums/built-in-variables">組み込み変数</a> と <a href="/MegaloEvolved/beta/docs/ja/language/enums/game-options">ゲームオプション</a> を参照。</p><h2 id="一時変数" tabindex="-1">一時変数 <a class="header-anchor" href="#一時変数" aria-label="Permalink to &quot;一時変数&quot;">​</a></h2><p>一時変数は <a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger#action-scope">アクションスコープ</a> — トリガー本体、<code>for_each</code> サブブロック、または <a href="/MegaloEvolved/beta/docs/ja/language/elements/begin"><code>begin</code></a> サブブロック — 内で宣言され、そのスコープの間だけ存在します。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">player_died</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-enumMember">enemy</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">player</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">player_death_get_killing_player</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span><span class="megalo-operator">.</span><span class="megalo-property">score</span><span class="megalo-text"> </span><span class="megalo-keyword">add</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>構文: <code>temporary &lt;type&gt; &lt;name&gt; &lt;initial_value&gt;</code></p><p>有効な型は <code>number</code>、<code>object</code>、<code>team</code>、<code>player</code> です。<code>timer</code> の一時変数はありません。</p><p>一時変数は、永続的な <a href="#custom-variables"><code>variables</code></a> スロットを宣言せずにゲッターアクションの結果や中間値を格納するのに便利です。各 <code>temporary</code> 行は初期値のための内部 <code>set</code> をコンパイラが出すため、スクリプトの 1024 アクション上限に対して <strong>アクション 1 つ</strong> としてもカウントされます。</p><p>一時プールのサイズとオーバーフロー上限は megalo バージョンに依存します。<a href="/MegaloEvolved/beta/docs/ja/versions/">バージョンページ</a> の <strong>Limits</strong> を参照 — <a href="/MegaloEvolved/beta/docs/ja/versions/107-mcc/#limits">107 (MCC)</a> は <a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger#action-scope">アクションスコープ</a> ごとの専用一時プールを使い、<a href="/MegaloEvolved/beta/docs/ja/versions/107/#limits">107</a> などの Xbox 360 ビルドは一時変数を直接グローバルにマップします。オーバーフロー挙動は <a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings#temporary-variable-overflow">コンパイラ設定 — 一時変数のオーバーフロー</a> で制御されます。</p><h2 id="特殊リテラル" tabindex="-1">特殊リテラル <a class="header-anchor" href="#特殊リテラル" aria-label="Permalink to &quot;特殊リテラル&quot;">​</a></h2><p>Megalo 全体で現れる 3 つの特殊な組み込み値:</p><table tabindex="0"><thead><tr><th>リテラル</th><th>意味</th></tr></thead><tbody><tr><td><code>true</code></td><td>真（1 として評価）</td></tr><tr><td><code>false</code></td><td>偽（0 として評価）</td></tr><tr><td><code>none</code></td><td>オブジェクト／プレイヤー／チームの null／空参照</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">condition if current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag equal_to none</span></span>
<span class="line"><span class="megalo-text">action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">body </span><span class="megalo-operator">=</span><span class="megalo-text"> my_body</span></span></code></pre></div><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/variables">要素 — variables</a> と <a href="/MegaloEvolved/beta/docs/ja/language/elements/constants">constants</a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/references">参照</a> — 変数がオペランドとして現れる方法</li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger/action">action</a> — <code>set</code> アクションと <a href="/MegaloEvolved/beta/docs/ja/language/enums/math-operations">数学演算</a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger">trigger</a> — トリガー内の <code>temporary</code> 変数</li><li><a href="/MegaloEvolved/beta/docs/ja/versions/">Megalo バージョン</a> — エンコーディングバージョンごとのコンパイル時制限</li></ul>`,52)])])}const b=e(t,[["render",o]]);export{i as __pageData,b as default};
